const QRCode=require('./vendor/QRCode'),level=require('./vendor/QRCode/QRErrorCorrectLevel');
const {gearRatioText,today}=require('../renderer/domain.js');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(db,car)=>`slotforge-paddock://car/${db.id}/${car.id}`;
function parseLink(value){try{const u=new URL(value);if(u.protocol!=='slotforge-paddock:'||u.hostname!=='car'||u.username||u.password||u.port||u.search||u.hash)return null;const [databaseId,carId,...rest]=u.pathname.slice(1).split('/');if(rest.length||![databaseId,carId].every(x=>/^[a-zA-Z0-9_-]{1,100}$/.test(x||'')))return null;return {databaseId,carId};}catch{return null;}}
function qr(value){const q=new QRCode(-1,level.M);q.addData(value);q.make();const n=q.getModuleCount();let d='';for(let y=0;y<n;y++)for(let x=0;x<n;x++)if(q.isDark(y,x))d+=`M${x+4} ${y+4}h1v1h-1z`;return `<svg class="report-qr" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${n+8} ${n+8}" aria-label="Open car in Paddock" shape-rendering="crispEdges"><rect width="100%" height="100%" fill="white"/><path d="${d}" fill="black"/></svg>`;}
const css=`body{font:12px Arial,sans-serif;color:#17212a;background:white;margin:0}.report{padding:20px}.report h1{font-size:24px}.report h2{font-size:19px}.report h3{font-size:14px}.report table{width:100%;border-collapse:collapse;margin:14px 0}.report th,.report td{border-bottom:1px solid #c9cfd5;padding:7px;text-align:left;overflow-wrap:anywhere}.report th{background:#edf1f5}.report-photo{width:58%;height:170px;object-fit:contain;float:right}.report-qr{width:86px;height:86px}.report-card{border:1px solid #bec8d2;border-radius:8px;padding:18px;margin-bottom:20px;break-inside:avoid;min-height:240px}.report small{color:#485969}.report p{overflow-wrap:anywhere}.report-sheet{break-after:page}.report-sheet:last-of-type{break-after:auto}.report .clear{clear:both}.report .writing{height:65px;border:1px solid #bbc4cd}.report a{color:inherit}@page{size:A4;margin:12mm}@media print{.report{padding:0}}`;
function render(db,p={}){
  if(p.revision!==undefined&&p.revision!==db.revision)throw Error('The database changed. Reopen the report preview.');
  if(!['cards','inventory','setup','scrutineering'].includes(p.kind))throw Error('Choose a report type.');
  if(!Array.isArray(p.ids)||p.ids.length<1||p.ids.length>500||new Set(p.ids).size!==p.ids.length)throw Error('Choose 1–500 different cars.');
  const cars=p.ids.map(id=>{const c=db.cars.find(c=>c.id===id);if(!c)throw Error('Car no longer exists.');return c;});
  const setup=p.setupId?db.setups.find(s=>s.id===p.setupId&&cars.length===1&&s.carId===cars[0].id):null;if(p.setupId&&!setup)throw Error('Choose a setup belonging to this car.');
  const title=({cards:'Car cards',inventory:'Collection inventory',setup:'Setup sheets',scrutineering:'Club scrutineering sheets'})[p.kind];
  const table=rows=>`<table><tbody>${rows.map(([k,v])=>`<tr><th>${esc(k)}</th><td>${esc(v||'—')}</td></tr>`).join('')}</tbody></table>`;
  let body=`<div class="report"><h1>${esc(title)}</h1><p>${esc(db.settings.name)}</p>`;
  if(p.kind==='inventory')body+=`<table><thead><tr>${['Number','Car','Maker','Scale','Location',...(p.purchase===true?['Acquired','Seller','Price','Currency']:[])].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${cars.map(c=>'<tr>'+[c.number,c.name,c.maker,c.scale,c.location,...(p.purchase===true?[c.acquired,c.seller,c.price,c.currency]:[])].map(x=>`<td>${esc(x||'—')}</td>`).join('')+'</tr>').join('')}</tbody></table><p>${cars.length} cars. Monetary values retain their individual currencies; no conversion or valuation is inferred.</p>`;
  else for(const c of cars){const t=setup?.technical||c.technical;body+=`<article class="${p.kind==='cards'?'report-card':'report-sheet'}"><h2>${esc(c.name)}</h2><p>${esc([c.number,c.maker,c.scale,c.raceClass].filter(Boolean).join(' · '))}</p>`;
    if(p.kind==='cards'){if(c.picture)body+=`<img class="report-photo" src="${esc(c.picture)}" alt="${esc(c.name)}">`;body+=`<a href="${esc(link(db,c))}">${qr(link(db,c))}</a><p><small>Open in Paddock on a computer<br>with this collection installed.</small></p><div class="clear"></div>`+table([['Motor',t.motor],['Gearing',[t.pinion,t.gear].filter(Boolean).join(' / ')],['Ratio',gearRatioText(t.pinion,t.gear)],['Rear tyres',t.rearTyres],['Weight',t.weight]]);}
    if(p.kind==='setup')body+=`<p>Configuration: ${esc(setup?setup.name+' · '+setup.date:'Current car')} ${setup?.track?'· '+esc(setup.track):''}</p>`+table(Object.entries(t).filter(([,v])=>v).map(([k,v])=>[k.replace(/([A-Z])/g,' $1'),v]))+`<h3>Tracked parts</h3>`+(setup&&(setup.sourceId||!setup.installations)?'<p>This historical setup has no tracked-inventory snapshot.</p>':table((setup?setup.installations:db.installations.filter(i=>i.carId===c.id&&!i.removed)).map(i=>[i.position||i.field,((setup?i.name:db.parts.find(p=>p.id===i.partId)?.name)||i.name||'Part')+' × '+i.quantity])));
    if(p.kind==='scrutineering')body+=table([['Class',c.raceClass],['Motor',t.motor],['Gear ratio',gearRatioText(t.pinion,t.gear)],['Weight (g)',t.weight],['Ground clearance',t.clearance],['Front width',t.frontWidth],['Rear width',t.rearWidth],['Rear tyre diameter',t.rearDiameter],['Magnets',t.magnets]])+'<p>Recorded specifications only. Verify against your club’s rules and actual measurements.</p><p>Inspector: ____________________ Date: ______________ Result: ______________</p><div class="writing"></div>';
    body+='</article>';
  }
  const printBody=body+'</div>',footer=`Generated by SlotForge Paddock · ${today()}`;
  body+=`<footer>${footer}</footer></div>`;
  const footerTemplate=`<div style="font:9px Arial,sans-serif;width:100%;padding:0 12mm;color:#485969">${footer}</div>`;
  return {title,body,css,footerTemplate,html:`<!doctype html><html><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>${esc(title)}</title><style>${css}</style></head><body>${printBody}</body></html>`};
}
module.exports={render,parseLink,link};
